/*
 * A071030  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 54".
 * https://oeis.org/A071030
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = the cell value in the n-th position (row‑major order) of
 *            the triangle obtained by iterating Rule 54 (3‑cell binary CA).
 *            Row r has length 2r+1; for n with r = ⌊√n⌋, the cell is at
 *            column j = n - r^2 in that row
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* Rule 54 truth table for neighbourhoods (left,mid,right): 
   000→0, 001→1, 010→1, 011→0, 100→1, 101→1, 110→0, 111→0.  */
static const uint8_t rule54[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    0, /* 011 */
    1, /* 100 */
    1, /* 101 */
    0, /* 110 */
    0  /* 111 */
};

/* Return floor(sqrt(n)) for an unsigned 64‑bit index. */
static idx_t int_sqrt(idx_t n) {
    /* use binary search to avoid floating point */
    idx_t low = 0, high = (idx_t)1 << 32;   /* high > sqrt(2^64) */
    while (low < high) {
        idx_t mid = (low + high + 1) >> 1;
        if (mid > 0 && mid > n / mid) {
            high = mid - 1;
        } else {
            low = mid;
        }
    }
    return low;
}

/* Compute a(n). */
seq_t a(idx_t n) {
    idx_t r = int_sqrt(n);           /* row number (0‑based) */
    idx_t j = n - r * r;             /* column index within that row */

    idx_t len = 1;
    uint8_t *prev = (uint8_t *)malloc(len * sizeof(uint8_t));
    if (!prev) return (seq_t)0;
    prev[0] = 1;

    for (idx_t cur = 1; cur <= r; ++cur) {
        idx_t newlen = 2 * cur + 1;
        uint8_t *next = (uint8_t *)malloc(newlen * sizeof(uint8_t));
        if (!next) { free(prev); return (seq_t)0; }

        for (idx_t k = 0; k < newlen; ++k) {
            uint8_t left  = (k >= 2 && (k - 2) < len) ? prev[k - 2] : 0;
            uint8_t mid   = (k >= 1 && (k - 1) < len) ? prev[k - 1] : 0;
            uint8_t right = (k <  len) ? prev[k] : 0;
            uint8_t idx   = (left << 2) | (mid << 1) | right;
            next[k] = rule54[idx];
        }

        free(prev);
        prev = next;
        len  = newlen;
    }

    uint8_t result = prev[j];
    free(prev);
    return (seq_t)result;
}
